#include "stdlib/lapack/base/dlasyf.h"
#include "validation.h"
#include "dlasyf_panel.h"

/**
* Computes a partial symmetric factorization using alternative indexing.
*
* @param uplo         selected matrix triangle
* @param N            matrix order
* @param NB           maximum factor panel width, at least two
* @param KB           scalar output number of factorized columns
* @param offsetKB     KB output index
* @param A            input/output matrix
* @param strideA1     first matrix dimension stride
* @param strideA2     second matrix dimension stride
* @param offsetA      matrix starting index
* @param IPIV         signed one-based pivot output
* @param strideIPIV   pivot stride
* @param offsetIPIV   pivot starting index
* @param W            N-by-NB workspace
* @param strideW1     first workspace dimension stride
* @param strideW2     second workspace dimension stride
* @param offsetW      workspace starting index
* @return             INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dlasyf_ndarray)( const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT NB, LAPACK_INT *KB, const LAPACK_INT offsetKB, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, LAPACK_INT *IPIV, const LAPACK_INT strideIPIV, const LAPACK_INT offsetIPIV, double *W, const LAPACK_INT strideW1, const LAPACK_INT strideW2, const LAPACK_INT offsetW ) {
	const intmax_t n = (intmax_t)N;
	const intmax_t nb = (intmax_t)NB;
	const double alpha = ( 1.0+sqrt( 17.0 ) )/8.0;
	dlasyf_view a;
	dlasyf_view w;
	LAPACK_INT error;
	LAPACK_INT info;
	intmax_t imax;
	intmax_t jmax;
	intmax_t kstep;
	intmax_t kkw;
	intmax_t kw;
	intmax_t kk;
	intmax_t kp;
	intmax_t jj;
	intmax_t jp;
	intmax_t k;
	intmax_t j;
	double absakk;
	double colmax;
	double rowmax;
	double d11;
	double d21;
	double d22;
	double r1;
	double t;

	error = dlasyf_validate( uplo, N, NB, KB, offsetKB, A, strideA1, strideA2, offsetA, IPIV, strideIPIV, offsetIPIV, W, strideW1, strideW2, offsetW );
	if ( error != 0 ) return dlasyf_error( "c_dlasyf_ndarray", error );
	if ( N == 0 ) {
		KB[ offsetKB ] = 0;
		return 0;
	}
	a.data = A;
	a.stride1 = strideA1;
	a.stride2 = strideA2;
	a.offset = offsetA;
	w.data = W;
	w.stride1 = strideW1;
	w.stride2 = strideW2;
	w.offset = offsetW;
	info = 0;

	if ( uplo == LAPACK_UPPER_TRIANGLE ) {
		// Factor the trailing panel in decreasing one-based column order.
		k = n;
		while ( k >= 1 && !( nb < n && k <= n-nb+1 ) ) {
			kw = nb-(n-k);
			dlasyf_copy( k, &a, 1, k, 0, &w, 1, kw, 0 );
			if ( k < n ) dlasyf_gemv( k, n-k, &a, 1, k+1, &w, k, kw+1, 1, kw );
			kstep = 1;
			absakk = fabs( DLASYF_CELL( &w, k, kw ) );
			imax = k;
			colmax = 0.0;
			if ( k > 1 ) {
				imax = 1+dlasyf_first_max( k-1, &w, 1, kw );
				colmax = fabs( DLASYF_CELL( &w, imax, kw ) );
			}
			if ( fmax( absakk, colmax ) == 0.0 ) {
				if ( info == 0 ) info = (LAPACK_INT)k;
				kp = k;
			} else {
				if ( k == 1 || absakk >= alpha*colmax ) {
					kp = k;
				} else {
					dlasyf_copy( imax, &a, 1, imax, 0, &w, 1, kw-1, 0 );
					dlasyf_copy( k-imax, &a, imax, imax+1, 1, &w, imax+1, kw-1, 0 );
					if ( k < n ) dlasyf_gemv( k, n-k, &a, 1, k+1, &w, imax, kw+1, 1, kw-1 );
					jmax = imax+1+dlasyf_first_max( k-imax, &w, imax+1, kw-1 );
					rowmax = fabs( DLASYF_CELL( &w, jmax, kw-1 ) );
					if ( imax > 1 ) {
						jmax = 1+dlasyf_first_max( imax-1, &w, 1, kw-1 );
						rowmax = fmax( rowmax, fabs( DLASYF_CELL( &w, jmax, kw-1 ) ) );
					}
					if ( absakk >= alpha*colmax*( colmax/rowmax ) ) {
						kp = k;
					} else if ( fabs( DLASYF_CELL( &w, imax, kw-1 ) ) >= alpha*rowmax ) {
						kp = imax;
						dlasyf_copy( k, &w, 1, kw-1, 0, &w, 1, kw, 0 );
					} else {
						kp = imax;
						kstep = 2;
					}
				}
				kk = k-kstep+1;
				kkw = nb-(n-kk);
				if ( kp != kk ) {
					DLASYF_CELL( &a, kp, kp ) = DLASYF_CELL( &a, kk, kk );
					dlasyf_copy( kk-1-kp, &a, kp+1, kk, 0, &a, kp, kp+1, 1 );
					if ( kp > 1 ) dlasyf_copy( kp-1, &a, 1, kk, 0, &a, 1, kp, 0 );
					if ( k < n ) dlasyf_swap( n-k, &a, kk, kp, k+1 );
					dlasyf_swap( n-kk+1, &w, kk, kp, kkw );
				}
					// The pivot-selection branch above sets kstep=2 for a 2-by-2 block.
					// cppcheck-suppress knownConditionTrueFalse
					if ( kstep == 1 ) {
					dlasyf_copy( k, &w, 1, kw, 0, &a, 1, k, 0 );
					r1 = 1.0/DLASYF_CELL( &a, k, k );
					dlasyf_scale( k-1, r1, &a, 1, k );
				} else {
					if ( k > 2 ) {
						d21 = DLASYF_CELL( &w, k-1, kw );
						d11 = DLASYF_CELL( &w, k, kw )/d21;
						d22 = DLASYF_CELL( &w, k-1, kw-1 )/d21;
						t = 1.0/( d11*d22-1.0 );
						d21 = t/d21;
						for ( j = 1; j <= k-2; j++ ) {
							DLASYF_CELL( &a, j, k-1 ) = d21*( d11*DLASYF_CELL( &w, j, kw-1 )-DLASYF_CELL( &w, j, kw ) );
							DLASYF_CELL( &a, j, k ) = d21*( d22*DLASYF_CELL( &w, j, kw )-DLASYF_CELL( &w, j, kw-1 ) );
						}
					}
					DLASYF_CELL( &a, k-1, k-1 ) = DLASYF_CELL( &w, k-1, kw-1 );
					DLASYF_CELL( &a, k-1, k ) = DLASYF_CELL( &w, k-1, kw );
					DLASYF_CELL( &a, k, k ) = DLASYF_CELL( &w, k, kw );
				}
			}
			IPIV[ (intmax_t)offsetIPIV+(k-1)*strideIPIV ] = (LAPACK_INT)(kstep == 1 ? kp : -kp);
			if ( kstep == 2 ) IPIV[ (intmax_t)offsetIPIV+(k-2)*strideIPIV ] = (LAPACK_INT)-kp;
			k -= kstep;
		}
		kw = nb-(n-k);
		if ( k > 0 && n-k > 0 ) dlasyf_triangular( uplo, k, n-k, &a, 1, 1, 1, k+1, &w, 1, kw+1 );
		j = k+1;
		while ( j <= n ) {
			jj = j;
			jp = IPIV[ (intmax_t)offsetIPIV+(j-1)*strideIPIV ];
			if ( jp < 0 ) {
				jp = -jp;
				j += 1;
			}
			j += 1;
			if ( jp != jj && j <= n ) dlasyf_swap( n-j+1, &a, jp, jj, j );
		}
		KB[ offsetKB ] = (LAPACK_INT)(n-k);
	} else {
		// Factor the leading panel in increasing one-based column order.
		k = 1;
		while ( k <= n && !( nb < n && k >= nb ) ) {
			dlasyf_copy( n-k+1, &a, k, k, 0, &w, k, k, 0 );
			if ( k > 1 ) dlasyf_gemv( n-k+1, k-1, &a, k, 1, &w, k, 1, k, k );
			kstep = 1;
			absakk = fabs( DLASYF_CELL( &w, k, k ) );
			imax = k;
			colmax = 0.0;
			if ( k < n ) {
				imax = k+1+dlasyf_first_max( n-k, &w, k+1, k );
				colmax = fabs( DLASYF_CELL( &w, imax, k ) );
			}
			if ( fmax( absakk, colmax ) == 0.0 ) {
				if ( info == 0 ) info = (LAPACK_INT)k;
				kp = k;
			} else {
				if ( k == n || absakk >= alpha*colmax ) {
					kp = k;
				} else {
					dlasyf_copy( imax-k, &a, imax, k, 1, &w, k, k+1, 0 );
					dlasyf_copy( n-imax+1, &a, imax, imax, 0, &w, imax, k+1, 0 );
					if ( k > 1 ) dlasyf_gemv( n-k+1, k-1, &a, k, 1, &w, imax, 1, k, k+1 );
					jmax = k+dlasyf_first_max( imax-k, &w, k, k+1 );
					rowmax = fabs( DLASYF_CELL( &w, jmax, k+1 ) );
					if ( imax < n ) {
						jmax = imax+1+dlasyf_first_max( n-imax, &w, imax+1, k+1 );
						rowmax = fmax( rowmax, fabs( DLASYF_CELL( &w, jmax, k+1 ) ) );
					}
					if ( absakk >= alpha*colmax*( colmax/rowmax ) ) {
						kp = k;
					} else if ( fabs( DLASYF_CELL( &w, imax, k+1 ) ) >= alpha*rowmax ) {
						kp = imax;
						dlasyf_copy( n-k+1, &w, k, k+1, 0, &w, k, k, 0 );
					} else {
						kp = imax;
						kstep = 2;
					}
				}
				kk = k+kstep-1;
				if ( kp != kk ) {
					DLASYF_CELL( &a, kp, kp ) = DLASYF_CELL( &a, kk, kk );
					dlasyf_copy( kp-kk-1, &a, kk+1, kk, 0, &a, kp, kk+1, 1 );
					if ( kp < n ) dlasyf_copy( n-kp, &a, kp+1, kk, 0, &a, kp+1, kp, 0 );
					if ( k > 1 ) dlasyf_swap( k-1, &a, kk, kp, 1 );
					dlasyf_swap( kk, &w, kk, kp, 1 );
				}
				if ( kstep == 1 ) {
					dlasyf_copy( n-k+1, &w, k, k, 0, &a, k, k, 0 );
					if ( k < n ) {
						r1 = 1.0/DLASYF_CELL( &a, k, k );
						dlasyf_scale( n-k, r1, &a, k+1, k );
					}
				} else {
					if ( k < n-1 ) {
						d21 = DLASYF_CELL( &w, k+1, k );
						d11 = DLASYF_CELL( &w, k+1, k+1 )/d21;
						d22 = DLASYF_CELL( &w, k, k )/d21;
						t = 1.0/( d11*d22-1.0 );
						d21 = t/d21;
						for ( j = k+2; j <= n; j++ ) {
							DLASYF_CELL( &a, j, k ) = d21*( d11*DLASYF_CELL( &w, j, k )-DLASYF_CELL( &w, j, k+1 ) );
							DLASYF_CELL( &a, j, k+1 ) = d21*( d22*DLASYF_CELL( &w, j, k+1 )-DLASYF_CELL( &w, j, k ) );
						}
					}
					DLASYF_CELL( &a, k, k ) = DLASYF_CELL( &w, k, k );
					DLASYF_CELL( &a, k+1, k ) = DLASYF_CELL( &w, k+1, k );
					DLASYF_CELL( &a, k+1, k+1 ) = DLASYF_CELL( &w, k+1, k+1 );
				}
			}
			IPIV[ (intmax_t)offsetIPIV+(k-1)*strideIPIV ] = (LAPACK_INT)(kstep == 1 ? kp : -kp);
			if ( kstep == 2 ) IPIV[ (intmax_t)offsetIPIV+k*strideIPIV ] = (LAPACK_INT)-kp;
			k += kstep;
		}
		// In a full panel k=N+1: skip before constructing any derived address.
		if ( k <= n && k > 1 ) dlasyf_triangular( uplo, n-k+1, k-1, &a, k, k, k, 1, &w, k, 1 );
		j = k-1;
		while ( j >= 1 ) {
			jj = j;
			jp = IPIV[ (intmax_t)offsetIPIV+(j-1)*strideIPIV ];
			if ( jp < 0 ) {
				jp = -jp;
				j -= 1;
			}
			j -= 1;
			if ( jp != jj && j >= 1 ) dlasyf_swap( j, &a, jp, jj, 1 );
		}
		KB[ offsetKB ] = (LAPACK_INT)(k-1);
	}
	return info;
}
